@@ -1,4 +1,18 @@
 /* Scale a raw ADC count by a power of two. */
 int scale(int raw, int shift) {
-  return raw << shift;
+  int factor;
+  const int int_max = 2147483647;
+  const int int_min = -2147483647 - 1;
+
+  if (shift < 0)
+    shift = 0;
+  else if (shift > 15)
+    shift = 15;
+
+  factor = 1 << shift;
+  if (raw > int_max / factor)
+    return int_max;
+  if (raw < int_min / factor)
+    return int_min;
+
+  return raw * factor;
 }

